#!/usr/bin/env osascript -l JavaScript

// JXA script to open a new VS Code window.
// Supports: VS Code, VS Code Insiders, and VSCodium.

ObjC.import("Foundation");

const FILE_MANAGER = $.NSFileManager.defaultManager;

// VS Code variants configuration (DRY principle)
const VS_CODE_VARIANTS = [
	{ name: "Visual Studio Code", path: "/Applications/Visual Studio Code.app" },
	{ name: "Visual Studio Code - Insiders", path: "/Applications/Visual Studio Code - Insiders.app" },
	{ name: "VSCodium", path: "/Applications/VSCodium.app" },
];

/**
 * Checks if an application exists at path.
 * @param {string} path - The path to check.
 * @returns {boolean}
 */
function appExists(path) {
	return FILE_MANAGER.fileExistsAtPath(path);
}

/**
 * Finds the installed VS Code variant.
 * Optimized: Uses centralized constant and functional find() method.
 * @returns {string|null} Application name or null if not found.
 */
function findVSCodeVariant() {
	const variant = VS_CODE_VARIANTS.find(v => appExists(v.path));
	return variant?.name || null;
}

/**
 * Main entry point to open a new VS Code window.
 * Optimized: Cleaner logic flow and better variable naming.
 */
function run() {
	"use strict";

	const appName = findVSCodeVariant();

	if (!appName) {
		return "VS Code not found";
	}

	// Initialize applications
	const VSCode = Application(appName);
	const SystemEvents = Application("System Events");
	VSCode.includeStandardAdditions = true;

	// Check if VS Code is already running
	const vscodeWasRunning = VSCode.running();

	// Open a new window
	if (!vscodeWasRunning) {
		VSCode.activate(); // Opens one window automatically
		delay(2);
	} else {
		VSCode.activate();
		// Open a new window using keyboard shortcut (Cmd + Shift + N)
		SystemEvents.keystroke("n", {
			using: ["command down", "shift down"],
		});
	}
}

ObjC.import("Foundation");

const FILE_MANAGER = $.NSFileManager.defaultManager;
const HOME = ObjC.unwrap(
	$.NSProcessInfo.processInfo.environment.objectForKey("HOME")
);

// VS Code variants configuration (DRY principle)
const VS_CODE_VARIANTS = [
	["Code", `${HOME}/Library/Application Support/Code/User/globalStorage/state.vscdb`],
	["Code - Insiders", `${HOME}/Library/Application Support/Code - Insiders/User/globalStorage/state.vscdb`],
	["VSCodium", `${HOME}/Library/Application Support/VSCodium/User/globalStorage/state.vscdb`],
];

/**
 * Executes a shell command using NSTask (faster than doShellScript)
 * @param {string} command - Command to execute
 * @returns {string|null} Output or null on error
 */
function runShell(command) {
	try {
		const task = $.NSTask.alloc.init;
		const stdout = $.NSPipe.pipe;

		task.launchPath = "/bin/zsh";
		task.arguments = ["-c", command];
		task.standardOutput = stdout;
		task.standardError = $.NSPipe.pipe;

		task.launch;
		task.waitUntilExit;

		if (task.terminationStatus !== 0) return null;

		const data = stdout.fileHandleForReading.readDataToEndOfFile;
		if (!data || data.length === 0) return null;

		return ObjC.unwrap(
			$.NSString.alloc.initWithDataEncoding(data, $.NSUTF8StringEncoding)
		);
	} catch (e) {
		return null;
	}
}

/**
 * Checks if a file exists at path
 */
function fileExists(path) {
	return FILE_MANAGER.fileExistsAtPath(path);
}

/**
 * Gets basename from path
 */
function getBasename(path) {
	const parts = path.split("/");
	return parts[parts.length - 1] || parts[parts.length - 2] || path;
}

/**
 * Gets dirname from path
 */
function getDirname(path) {
	const parts = path.split("/");
	parts.pop();
	return parts.join("/") || "/";
}

/**
 * Gets git branches for multiple paths in parallel (much faster)
 * @param {string[]} paths - Array of directory paths
 * @returns {Object} Map of path -> branch name
 */
function getGitBranchesParallel(paths) {
    if (paths.length === 0) return {};

    // Create a script that outputs "path:branch" for each repo
    const script = paths.map(p =>
        `(cd "${p}" 2>/dev/null && echo "${p}:$(git rev-parse --abbrev-ref HEAD 2>/dev/null)")`
    ).join(" & ");

    const result = runShell(`{ ${script}; wait; } 2>/dev/null`);
    if (!result) return {};

    const branches = {};
    result.trim().split("\n").forEach(line => {
        const colonIndex = line.lastIndexOf(":");
        if (colonIndex > 0) {
            const path = line.substring(0, colonIndex);
            const branch = line.substring(colonIndex + 1);
            if (branch && branch !== "HEAD") {
                branches[path] = branch;
            }
        }
    });
    return branches;
}

/**
 * Finds VS Code database path.
 * Optimized: Uses centralized VS_CODE_VARIANTS constant.
 */
function findVSCodeDB() {
	for (const [name, path] of VS_CODE_VARIANTS) {
		if (fileExists(path)) {
			return { dbPath: path, buildName: name };
		}
	}
	return null;
}

/**
 * Reads recent entries from VS Code SQLite database.
 * Optimized: Single try-catch block, optional chaining.
 */
function getRecentEntries(dbPath) {
    const query = `SELECT json_extract(value, '$.entries') FROM ItemTable WHERE key = 'history.recentlyOpenedPathsList';`;
	const result = runShell(`/usr/bin/sqlite3 "${dbPath}" "${query}"`);
    const storagePath = dbPath.replace(/state\.vscdb$/, "storage.json");

    if (!result) return getRecentEntriesFromStorage(storagePath);

	try {
        const trimmed = result.trim();
        if (!trimmed || trimmed.toLowerCase() === "null") {
            return getRecentEntriesFromStorage(storagePath);
        }
        const entries = JSON.parse(trimmed) || [];
        return entries.length ? entries : getRecentEntriesFromStorage(storagePath);
	} catch (e) {
        return getRecentEntriesFromStorage(storagePath);
	}
}

/**
 * Fallback for VS Code versions where recent paths moved from state.vscdb
 * to globalStorage/storage.json.
 */
function getRecentEntriesFromStorage(storagePath) {
    if (!fileExists(storagePath)) return [];

    try {
        const content = ObjC.unwrap(
            $.NSString.stringWithContentsOfFileEncodingError(
                storagePath,
                $.NSUTF8StringEncoding,
                null
            )
        );
        if (!content) return [];

        const data = JSON.parse(content);
        const recentMenuItems = data.lastKnownMenubarData?.menus?.File?.items
            ?.find((item) => item.id === "submenuitem.MenubarRecentMenu")
            ?.submenu?.items || [];

        return recentMenuItems.flatMap((item) => {
            if (item.id === "openRecentFolder" && item.uri?.path) {
                return { folderUri: `file://${item.uri.path}` };
            }
            if (item.id === "openRecentFile" && item.uri?.path) {
                return { fileUri: `file://${item.uri.path}` };
            }
            return [];
        });
    } catch (e) {
        return [];
    }
}

/**
 * Parses a URI string to a local file path
 * @param {string} uri - URI to parse
 * @returns {string|null} Local path or null if remote/invalid
 */
function parseUri(uri) {
	if (!uri || uri.startsWith("vscode-remote://")) return null;
	return decodeURIComponent(uri.replace("file://", ""));
}

/**
 * Extracts path and type from an entry
 * @param {Object} entry - Entry object
 * @returns {{path: string, type: string, name: string}|null}
 */
function extractEntryInfo(entry) {
	if (entry.folderUri) {
		const path = parseUri(entry.folderUri);
		return path ? { path, type: "folder", name: getBasename(path) } : null;
	}

	if (entry.workspace?.configPath) {
		const path = parseUri(entry.workspace.configPath);
		return path ? { path, type: "workspace", name: getBasename(path).replace(".code-workspace", "") } : null;
	}

	if (entry.fileUri) {
		const path = parseUri(entry.fileUri);
		return path ? { path, type: "file", name: getBasename(path) } : null;
	}

	return null;
}

/**
 * Creates error/info item for Alfred.
 * DRY: Extracted common pattern for error messages.
 * @param {string} title - Title of the message.
 * @param {string} subtitle - Subtitle of the message.
 * @param {string} iconPath - Optional icon path.
 * @returns {object} Alfred response object.
 */
function createInfoItem(title, subtitle, iconPath = "icon.png") {
	return {
		items: [{ title, subtitle, valid: false, icon: { path: iconPath } }]
	};
}

/**
 * Parses a single entry into Alfred item format
 * @param {Object} entry - Entry object
 * @param {Object} branchMap - Map of path -> branch name
 */
function parseEntry(entry, branchMap = {}) {
    const info = extractEntryInfo(entry);
    if (!info || !fileExists(info.path)) return null;

    const { path, type, name } = info;
    const prettyPath = path.replace(HOME, "~");
    const dirPath = getDirname(prettyPath);

    // Get git branch from pre-fetched map (only for folders)
    const branch = type === "folder" ? branchMap[path] : null;
    const subtitle = branch ? `${dirPath} • ${branch}` : dirPath;

    return {
        uid: path,
        title: name,
        subtitle: subtitle,
        arg: path,
        autocomplete: name,
        match: `${name} ${path}`,
        type: "file",
        icon: type === "workspace"
            ? { path: "workspace.png" }
            : { type: "fileicon", path: path },
        mods: {
            // ctrl: {
            // 	subtitle: "⌃ Remove from recent projects",
            // 	arg: `remove:${path}`,
            // },
            // "ctrl+shift": {
            // 	subtitle: "⌃⇧ Remove all recent projects",
            // 	arg: "remove:all",
            // },
        },
    };
}

/**
 * Main entry point for Alfred Script Filter.
 * Optimized: Uses createInfoItem, cleaner error handling.
 */
function run() {
    const vsCode = findVSCodeDB();

    if (!vsCode) {
        return JSON.stringify(createInfoItem(
            "VS Code not found",
            "Could not locate VS Code database"
        ));
    }

    const entries = getRecentEntries(vsCode.dbPath);

    if (!entries.length) {
        return JSON.stringify(createInfoItem(
            "No recent projects",
            "Open some projects in VS Code first"
        ));
    }

    // Extract folder paths for parallel git branch fetching
    const folderPaths = entries
        .map(extractEntryInfo)
        .filter(info => info?.type === "folder" && fileExists(info.path))
        .map(info => info.path);

    // Fetch all git branches in parallel (single shell call)
    const branchMap = getGitBranchesParallel(folderPaths);

    // Parse entries and filter out null values
    const items = entries
        .map(entry => parseEntry(entry, branchMap))
        .filter(item => item !== null);

    return JSON.stringify({
        cache: { seconds: 5, loosereload: true },
        items,
    });
}

#!/usr/bin/env osascript -l JavaScript

// JXA script to uninstall a VS Code extension from an Alfred workflow.
// It finds the installed VS Code variant and uses its command-line interface
// to uninstall the extension passed as an argument.

ObjC.import("Foundation");

const FILE_MANAGER = $.NSFileManager.defaultManager;
const app = Application.currentApplication();
app.includeStandardAdditions = true;

// Consistent VS Code variants configuration
const VS_CODE_VARIANTS = [
	{
		name: "Visual Studio Code",
		path: "/Applications/Visual Studio Code.app",
		cli: "code",
	},
	{
		name: "Visual Studio Code - Insiders",
		path: "/Applications/Visual Studio Code - Insiders.app",
		cli: "code-insiders",
	},
	{ name: "VSCodium", path: "/Applications/VSCodium.app", cli: "codium" },
];

/**
 * Checks if a file or directory exists.
 * @param {string} path - The path to check.
 * @returns {boolean}
 */
function fileExists(path) {
	return FILE_MANAGER.fileExistsAtPath(path);
}

/**
 * Finds the first installed VS Code variant.
 * @returns {{name: string, path: string, cli: string}|null}
 */
function findVSCodeVariant() {
	return VS_CODE_VARIANTS.find(variant => fileExists(variant.path)) || null;
}

/**
 * Executes a shell command.
 * @param {string} command - The command to execute.
 * @returns {string|null} The result of the command, or null on error.
 */
function runShell(command) {
	try {
		return app.doShellScript(command);
	} catch (e) {
		console.log(`Error executing command: ${command}`);
		console.log(e.message);
		return null;
	}
}

/**
 * Main entry point for the JXA script.
 * @param {string[]} argv - Arguments passed from the Alfred Run Script action.
 */
function run(argv) {
	"use strict";

	const extensionId = argv?.[0]?.trim();
	if (!extensionId) {
		return "No extension ID provided";
	}

	// Get the extension name from environment variable if available
	const env = $.NSProcessInfo.processInfo.environment;
	const extensionName = ObjC.unwrap(env.objectForKey("extension_name")) || extensionId;

	const vscode = findVSCodeVariant();
	if (!vscode) {
		return "Application not detected on this system. Please install VS Code first.";
	}

	// Use the full path to the binary inside the app bundle.
	const cliPath = `${vscode.path}/Contents/Resources/app/bin/${vscode.cli}`;
	const command = `'${cliPath}' --uninstall-extension '${extensionId}'`;

	const result = runShell(command);

	if (result === null) {
		return `${extensionName}\nUninstall failed. Please try again.`;
	}

	return `${extensionName}\nUninstalled successfully`;
}

#!/usr/bin/env osascript -l JavaScript

// JXA script to list installed VS Code extensions from an Alfred workflow.
// It finds all installed VS Code variants and displays their installed extensions
// with support for opening them directly in VS Code or uninstalling them.

ObjC.import("Foundation");

const FILE_MANAGER = $.NSFileManager.defaultManager;
const HOME = ObjC.unwrap(
	$.NSProcessInfo.processInfo.environment.objectForKey("HOME")
);

// VS Code variants configuration (DRY principle)
const VS_CODE_VARIANTS = [
	{
		name: "Code",
		app: "/Applications/Visual Studio Code.app",
		ext: ".vscode",
		scheme: "vscode",
	},
	{
		name: "Code - Insiders",
		app: "/Applications/Visual Studio Code - Insiders.app",
		ext: ".vscode-insiders",
		scheme: "vscode-insiders",
	},
	{
		name: "VSCodium",
		app: "/Applications/VSCodium.app",
		ext: ".vscode-oss",
		scheme: "vscodium",
	},
];

/**
 * Checks if a file or directory exists.
 * @param {string} path - The path to check.
 * @returns {boolean}
 */
function fileExists(path) {
	return FILE_MANAGER.fileExistsAtPath(path);
}

/**
 * Finds installed VS Code variants and their extension directories.
 * Optimized: Only checks paths once, constructs result directly.
 * @returns {{name: string, extensionsPath: string, scheme: string}[]}
 */
function findVSCodeVariants() {
	return VS_CODE_VARIANTS.map((v) => ({
		...v,
		extensionsPath: `${HOME}/${v.ext}/extensions`,
	})).filter((v) => fileExists(v.extensionsPath));
}

/**
 * Reads and parses a JSON file with caching.
 * Optimized: Single try-catch, early return pattern.
 * @param {string} path - Path to the JSON file.
 * @returns {object|null}
 */
function readJson(path) {
	try {
		const content = $.NSString.stringWithContentsOfFileEncodingError(
			path,
			$.NSUTF8StringEncoding,
			null
		);
		return content ? JSON.parse(ObjC.unwrap(content)) : null;
	} catch (e) {
		return null;
	}
}

/**
 * Resolves localization tokens in a string (e.g., %displayName%).
 * Optimized: Early return, lazy loading of NLS file.
 * @param {string} value - Value that may contain localization tokens.
 * @param {string} extPath - Path to the extension directory.
 * @returns {string}
 */
function resolveLocalization(value, extPath) {
	if (!value || typeof value !== "string" || !value.includes("%")) {
		return value;
	}

	const nls = readJson(`${extPath}/package.nls.json`);
	return nls
		? value.replace(/%([^%]+)%/g, (_, token) => nls[token] || `%${token}%`)
		: value;
}

/**
 * Gets the icon path for an extension.
 * Optimized: Trust manifest.icon if present, otherwise use default.
 * @param {string} extPath - Path to the extension directory.
 * @param {object} manifest - The package.json manifest.
 * @returns {object} Icon object for Alfred.
 */
function findExtensionIcon(extPath, manifest) {
	// Trust manifest-specified icon (VS Code validates this)
	if (manifest.icon) {
		return { path: `${extPath}/${manifest.icon}` };
	}
	return { path: "icon.png" };
}

/**
 * Creates an Alfred item from extension metadata.
 * Optimized: Extracted to separate function for better readability and reusability.
 * @param {string} id - Extension ID.
 * @param {string} displayName - Display name of the extension.
 * @param {string} description - Description of the extension.
 * @param {string} publisher - Publisher name.
 * @param {object} icon - Icon object.
 * @param {object} variant - The VS Code variant this extension belongs to.
 * @returns {object} Alfred item object.
 */
function createAlfredItem(
	id,
	displayName,
	description,
	publisher,
	icon,
	variant
) {
	const vscodeUrl = `${variant.scheme}:extension/${id}`;
	return {
		uid: id,
		title: displayName,
		subtitle: description,
		arg: vscodeUrl,
		autocomplete: displayName,
		match: `${displayName} ${publisher} ${id}`,
		icon: icon,
		mods: {
			ctrl: {
				subtitle: `⌃ Uninstall "${displayName}"`,
				arg: id,
				variables: { action: "uninstall", extension_name: displayName },
			},
		},
	};
}

/**
 * Gets the set of obsolete (pending removal) extension folder names.
 * VS Code marks uninstalled extensions in a .obsolete JSON file.
 * @param {string} extensionsPath - Path to the extensions directory.
 * @returns {Set<string>} Set of obsolete folder names.
 */
function getObsoleteExtensions(extensionsPath) {
	const obsoleteFile = `${extensionsPath}/.obsolete`;
	const obsoleteData = readJson(obsoleteFile);
	return obsoleteData ? new Set(Object.keys(obsoleteData)) : new Set();
}

/**
 * Gets locally installed extensions.
 * Optimized: Streamlined logic, reduced nesting, better error handling.
 * @param {object} variant - The VS Code variant object.
 * @returns {object[]}
 */
function getLocalExtensions(variant) {
	const extensionsPath = variant.extensionsPath;
	if (!fileExists(extensionsPath)) return [];

	const contents = FILE_MANAGER.contentsOfDirectoryAtPathError(
		extensionsPath,
		null
	);
	if (!contents) return [];

	// Get obsolete extensions to filter them out
	const obsolete = getObsoleteExtensions(extensionsPath);

	const extensions = [];
	const count = contents.count;

	for (let i = 0; i < count; i++) {
		const dirName = ObjC.unwrap(contents.objectAtIndex(i));

		// Skip obsolete (uninstalled) extensions
		if (obsolete.has(dirName)) continue;

		const extPath = `${extensionsPath}/${dirName}`;
		const manifest = readJson(`${extPath}/package.json`);

		if (!manifest?.name || !manifest?.publisher) continue;

		const id = `${manifest.publisher}.${manifest.name}`;
		const displayName =
			resolveLocalization(manifest.displayName, extPath) || manifest.name;
		const description =
			resolveLocalization(manifest.description, extPath) || "";
		const icon = findExtensionIcon(extPath, manifest);

		extensions.push(
			createAlfredItem(
				id,
				displayName,
				description,
				manifest.publisher,
				icon,
				variant
			)
		);
	}

	return extensions;
}

/**
 * Creates error/info item for Alfred.
 * DRY: Extracted common pattern for error messages.
 * @param {string} title - Title of the message.
 * @param {string} subtitle - Subtitle of the message.
 * @returns {object} Alfred response object.
 */
function createInfoItem(title, subtitle) {
	return {
		items: [{ title, subtitle, valid: false }],
	};
}

/**
 * Main entry point for Alfred Script Filter.
 * Optimized: Reduced complexity, better data flow, single JSON.stringify call.
 */
function run() {
	const variants = findVSCodeVariants();

	if (variants.length === 0) {
		return JSON.stringify(
			createInfoItem(
				"VS Code installation not found",
				"Could not locate VS Code, Insiders, or VSCodium extensions."
			)
		);
	}

	// Collect all extensions from all variants
	const allExtensions = variants.flatMap((v) => getLocalExtensions(v));

	if (allExtensions.length === 0) {
		return JSON.stringify(
			createInfoItem(
				"No extensions found",
				"Could not find any installed extensions."
			)
		);
	}

	// Remove duplicates using Map (O(n) instead of O(n²))
	const uniqueExtensions = Array.from(
		new Map(allExtensions.map((item) => [item.uid, item])).values()
	);

	// Sort alphabetically (case-insensitive)
	uniqueExtensions.sort((a, b) => a.title.localeCompare(b.title));

	return JSON.stringify({
		cache: { seconds: 5, loosereload: true },
		items: uniqueExtensions,
	});
}

ObjC.import("Foundation");

const app = Application.currentApplication();
app.includeStandardAdditions = true;

const FILE_MANAGER = $.NSFileManager.defaultManager;
const HOME = ObjC.unwrap($.NSProcessInfo.processInfo.environment.objectForKey("HOME"));
const MAX_RESULTS = 20;
const API_URL = "https://marketplace.visualstudio.com/_apis/public/gallery/extensionquery?api-version=3.0-preview.1";
const MARKETPLACE_URL = "https://marketplace.visualstudio.com/items?itemName=";
const DEFAULT_ICON = "icon.png";

// Consistent VS Code variants configuration
const VS_CODE_VARIANTS = [
    { name: "Code", ext: ".vscode", path: "/Applications/Visual Studio Code.app", scheme: "vscode" },
    { name: "Code - Insiders", ext: ".vscode-insiders", path: "/Applications/Visual Studio Code - Insiders.app", scheme: "vscode-insiders" },
    { name: "VSCodium", ext: ".vscode-oss", path: "/Applications/VSCodium.app", scheme: "vscodium" },
];

// API Flags (combined for performance)
const API_FLAGS = 0x2 | 0x4 | 0x10 | 0x20 | 0x80 | 0x100 | 0x200; // Files, Categories, VersionProps, ExcludeNonValidated, AssetUri, Statistics, LatestOnly

/**
 * Checks if a file or directory exists.
 * @param {string} path - The path to check.
 * @returns {boolean}
 */
function fileExists(path) {
    return FILE_MANAGER.fileExistsAtPath(path);
}

/**
 * Finds the first installed VS Code variant.
 * @returns {{name: string, path: string, cli: string, scheme: string}|null}
 */
function findVSCodeVariant() {
	return VS_CODE_VARIANTS.find(variant => fileExists(variant.path)) || null;
}

/**
 * Executes a shell command
 */
function runShell(command) {
	try {
		return app.doShellScript(command);
	} catch (e) {
		return null;
	}
}

/**
 * Formats number compactly (1.2K, 3.4M)
 */
function compactNumber(num) {
	if (num >= 1e6) return (num / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
	if (num >= 1e3) return (num / 1e3).toFixed(1).replace(/\.0$/, "") + "K";
	return String(num);
}

/**
 * Reads and parses a JSON file.
 * @param {string} path - Path to the JSON file.
 * @returns {object|null}
 */
function readJson(path) {
	try {
		const content = $.NSString.stringWithContentsOfFileEncodingError(
			path,
			$.NSUTF8StringEncoding,
			null
		);
		return content ? JSON.parse(ObjC.unwrap(content)) : null;
	} catch (e) {
		return null;
	}
}

/**
 * Gets the set of obsolete (pending removal) extension folder names.
 * VS Code marks uninstalled extensions in a .obsolete JSON file.
 * @param {string} extensionsPath - Path to the extensions directory.
 * @returns {Set<string>} Set of obsolete folder names.
 */
function getObsoleteExtensions(extensionsPath) {
	const obsoleteFile = `${extensionsPath}/.obsolete`;
	const obsoleteData = readJson(obsoleteFile);
	return obsoleteData ? new Set(Object.keys(obsoleteData)) : new Set();
}

/**
 * Reads installed extension IDs from all found VS Code variants.
 * @returns {Set<string>} A set of installed extension IDs (lowercase).
 */
function getInstalledExtensions() {
    const ids = new Set();
    if (!HOME) return ids;

    const variantPaths = VS_CODE_VARIANTS
        .map(v => `${HOME}/${v.ext}/extensions`)
        .filter(path => fileExists(path));

    for (const extPath of variantPaths) {
        // Get obsolete extensions to filter them out
        const obsolete = getObsoleteExtensions(extPath);

        const contents = FILE_MANAGER.contentsOfDirectoryAtPathError(extPath, null);
        if (!contents) continue;

        const count = contents.count;
        for (let i = 0; i < count; i++) {
            const dirName = ObjC.unwrap(contents.objectAtIndex(i));

            // Skip obsolete (uninstalled) extensions
            if (obsolete.has(dirName)) continue;

            // Extract ID: "ms-python.python-2.0.1" -> "ms-python.python"
            const match = dirName.match(/^(.+?)-\d/);
            if (match) ids.add(match[1].toLowerCase());
        }
    }
    return ids;
}

/**
 * Fetches extensions from VS Code Marketplace
 */
function fetchExtensions(searchText) {
	const body = JSON.stringify({
		filters: [
			{
				criteria: [
					{ filterType: 8, value: "Microsoft.VisualStudio.Code" },
					{ filterType: 10, value: searchText },
					{ filterType: 12, value: "4096" },
				],
				pageNumber: 1,
				pageSize: MAX_RESULTS,
				sortBy: 0,
				sortOrder: 0,
			},
		],
		assetTypes: [],
		flags: API_FLAGS,
	});

	const command = `curl -s -X POST '${API_URL}' -H 'Content-Type: application/json' --compressed -d '${body}' --max-time 8`;
	const result = runShell(command);

	if (!result) return [];

	try {
		const data = JSON.parse(result);
		return data.results?.[0]?.extensions || [];
	} catch (e) {
		return [];
	}
}

/**
 * Parses extension to Alfred item
 */
function parseExtension(ext, installedIds, vscodeVariant) {
	const id = `${ext.publisher.publisherName}.${ext.extensionName}`;
	const stats = ext.statistics?.find((s) => s.statisticName === "install");
	const version = ext.versions?.[0]?.version || "";
	const isInstalled = installedIds.has(id.toLowerCase());

	const subtitle = [
		isInstalled ? "✓ Installed" : null,
		ext.publisher.displayName,
		stats ? `↓ ${compactNumber(stats.value)}` : null,
		version ? `v${version}` : null,
	]
		.filter(Boolean)
		.join(" • ");

	const vscodeUrl = vscodeVariant ? `${vscodeVariant.scheme}:extension/${id}` : MARKETPLACE_URL + id;

	return {
		uid: ext.extensionId,
		title: ext.displayName,
		subtitle,
		arg: id,
		autocomplete: ext.displayName,
		match: `${ext.displayName} ${id} ${ext.shortDescription || ""}`,
		text: { copy: id, largetype: ext.shortDescription || ext.displayName },
		quicklookurl: MARKETPLACE_URL + id,
		icon: { path: DEFAULT_ICON },
		variables: { extension_name: ext.displayName },
		mods: {
			cmd: {
				subtitle: `⌘ Open in VS Code`,
				arg: vscodeUrl,
			},
		},
	};
}

/**
 * Creates a simple Alfred item
 */
function simpleItem(title, subtitle, valid = false) {
	return { title, subtitle, valid, icon: { path: DEFAULT_ICON } };
}

/**
 * Main entry point
 */
function run(argv) {
	const query = argv?.[0]?.trim() || "";

	if (!query) {
		return JSON.stringify({
			items: [
				simpleItem(
					"Search VS Code Extensions",
					"Type to search the Marketplace"
				),
			],
		});
	}

	const extensions = fetchExtensions(query);

	if (!extensions.length) {
		return JSON.stringify({
			items: [
				simpleItem("No extensions found", `No results for "${query}"`),
			],
		});
	}

	const installedIds = getInstalledExtensions();
	const vscodeVariant = findVSCodeVariant();

	return JSON.stringify({
		cache: { seconds: 5, loosereload: true },
		items: extensions.map((ext) => parseExtension(ext, installedIds, vscodeVariant)),
	});
}

#!/usr/bin/env osascript -l JavaScript

// JXA script to install a VS Code extension from an Alfred workflow.
// It finds the installed VS Code variant and uses its command-line interface
// to install the extension passed as an argument.

ObjC.import("Foundation");

const FILE_MANAGER = $.NSFileManager.defaultManager;
const app = Application.currentApplication();
app.includeStandardAdditions = true;

// Consistent VS Code variants configuration
const VS_CODE_VARIANTS = [
	{
		name: "Visual Studio Code",
		path: "/Applications/Visual Studio Code.app",
		cli: "code",
	},
	{
		name: "Visual Studio Code - Insiders",
		path: "/Applications/Visual Studio Code - Insiders.app",
		cli: "code-insiders",
	},
	{ name: "VSCodium", path: "/Applications/VSCodium.app", cli: "codium" },
];

/**
 * Checks if a file or directory exists.
 * @param {string} path - The path to check.
 * @returns {boolean}
 */
function fileExists(path) {
	return FILE_MANAGER.fileExistsAtPath(path);
}

/**
 * Finds the first installed VS Code variant.
 * @returns {{name: string, path: string, cli: string}|null}
 */
function findVSCodeVariant() {
	return VS_CODE_VARIANTS.find(variant => fileExists(variant.path)) || null;
}

/**
 * Executes a shell command.
 * @param {string} command - The command to execute.
 * @returns {string|null} The result of the command, or null on error.
 */
function runShell(command) {
	try {
		return app.doShellScript(command);
	} catch (e) {
		console.log(`Error executing command: ${command}`);
		console.log(e.message);
		return null;
	}
}

/**
 * Main entry point for the JXA script.
 * @param {string[]} argv - Arguments passed from the Alfred Run Script action.
 */
function run(argv) {
	"use strict";

	const extensionId = argv?.[0]?.trim();
	if (!extensionId) {
		return "No extension ID provided";
	}

	// Get the extension name from environment variable if available
	const env = $.NSProcessInfo.processInfo.environment;
	const extensionName = ObjC.unwrap(env.objectForKey("extension_name")) || extensionId;

	const vscode = findVSCodeVariant();
	if (!vscode) {
		return "Application not detected on this system. Please install VS Code first.";
	}

	// Use the full path to the binary inside the app bundle.
	const cliPath = `${vscode.path}/Contents/Resources/app/bin/${vscode.cli}`;
	const command = `'${cliPath}' --install-extension '${extensionId}' --force`;

	const result = runShell(command);

	if (result === null) {
		return `${extensionName}\nInstallation failed. Please try again.`;
	}

	return `${extensionName}\nInstalled successfully`;
}
